using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using LoanService;
using Microsoft.EntityFrameworkCore;
using RabbitMQ.Client;
using Shared;
using WebhookApi;
using Xunit;

namespace Integration.Tests;
#pragma warning disable EF1002 // DDL names/payload in the rollback test are internally generated hex GUIDs; SQL identifiers cannot be bound as parameters.
// Uses the real running demo infrastructure. Each test originates a unique fictional loan;
// no reset/truncation or edits of existing posted financial records are performed.
public class PipelineTests
{
    private static string Env(string key,string fallback)=>Environment.GetEnvironmentVariable(key)??fallback;
    private static string Connection(string name)=>$"Host=localhost;Database={name};Username={name};Password={Env(name.ToUpperInvariant()+"_DB_PASSWORD","local-"+name+"-db-password-2026")};Maximum Pool Size=10";
    private static LoanDb Db()=>new(new DbContextOptionsBuilder<LoanDb>().UseNpgsql(Connection("loan")).Options);
    private static ReceiptDb Receipts()=>new(new DbContextOptionsBuilder<ReceiptDb>().UseNpgsql(Connection("webhook")).Options);
    private static string Identity()=>Guid.NewGuid().ToString("N");
    private static BankPayment Payment(string reference,string? id=null,string amount="900000",string outcome="SUCCEEDED") {id??=Identity();return new("test-evt-"+id,"test-tx-"+id,reference,amount,"THB",outcome,new(2026,10,31,16,59,0,TimeSpan.FromHours(7)));}
    private static PaymentReceived Envelope(BankPayment p)=>new(p.EventId,p.BankTransactionId,"demo-bank",DateTimeOffset.UtcNow,1,Identity(),null,p,DateTimeOffset.UtcNow);
    private static async Task<string> Originate(){await using var db=Db();var r="TEST-"+Identity();db.Loans.Add(new(){Reference=r,Customer="Fictional integration customer",OpeningPrincipal=10_000_000,OutstandingPrincipal=10_000_000,AnnualRate=.12m,MonthlyPayment=900_000,Installments=Finance.Schedule(10_000_000,.12m,900_000,new(2026,10,31))});await db.SaveChangesAsync();return r;}
    private static async Task<HttpResponseMessage> Deliver(BankPayment p,bool valid=true){var body=JsonSerializer.Serialize(p,Contracts.Json);var stamp=DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();using var req=new HttpRequestMessage(HttpMethod.Post,Env("TEST_WEBHOOK_URL","http://localhost:5101")+"/webhooks/bank/payments"){Content=new StringContent(body,Encoding.UTF8,"application/json")};req.Headers.Add("X-Bank-Timestamp",stamp);req.Headers.Add("X-Bank-Signature",valid?Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(Env("BANK_SECRET","local-demo-bank-signing-secret-change-me-2026")),Encoding.UTF8.GetBytes(stamp+"."+body))):new string('0',64));using var client=new HttpClient();return await client.SendAsync(req);}
    private static async Task<AppliedPayment> WaitPayment(string id){for(var i=0;i<100;i++){await using var db=Db();var p=await db.Payments.AsNoTracking().Include(x=>x.Allocations).SingleOrDefaultAsync(x=>x.BankTransactionId==id);if(p is not null)return p;await Task.Delay(100);}throw new TimeoutException("Financial worker did not process "+id);}
    private static async Task<HttpClient> Client(string role){var handler=new HttpClientHandler{CookieContainer=new CookieContainer()};var client=new HttpClient(handler){BaseAddress=new Uri(Env("TEST_DEMO_URL","http://localhost:5100"))};using var response=await client.PostAsJsonAsync("/api/v1/auth/login",new {role,password=Env(role=="Admin"?"ADMIN_PASSWORD":"OBSERVER_PASSWORD",role=="Admin"?"demo-admin-password":"demo-observer-password")});response.EnsureSuccessStatusCode();return client;}
    [Fact]public async Task Receipt_and_outbox_are_durable_before_200(){var p=Payment(await Originate());using var response=await Deliver(p);Assert.Equal(HttpStatusCode.OK,response.StatusCode);await using var db=Receipts();Assert.True(await db.Receipts.AnyAsync(x=>x.EventId==p.EventId));Assert.True(await db.Outbox.AnyAsync(x=>x.Identity=="demo-bank:"+p.EventId));}
    [Fact]public async Task Run_context_survives_receipt_processing_and_result_event()
    {
        var runId=Guid.NewGuid();var payment=Payment(await Originate()) with {RunId=runId};using(var delivered=await Deliver(payment))delivered.EnsureSuccessStatusCode();
        var applied=await WaitPayment(payment.BankTransactionId);await using var receipts=Receipts();var incoming=await receipts.Outbox.SingleAsync(x=>x.Identity=="demo-bank:"+payment.EventId);
        Assert.Equal(runId,JsonSerializer.Deserialize<PaymentReceived>(incoming.Payload,Contracts.Json)!.RunId);
        await using var db=Db();var result=await db.Outbox.SingleAsync(x=>x.Identity=="result:"+applied.Id+":"+applied.Status);Assert.Equal(runId,JsonSerializer.Deserialize<PaymentResult>(result.Payload,Contracts.Json)!.RunId);
        using var client=await Client("Admin");var summary=await client.GetFromJsonAsync<JsonObject>("/api/v1/run-application/"+runId);Assert.Equal(1,summary!["appliedUnique"]!.GetValue<int>());
    }
    [Fact]public async Task Failed_outbox_insert_rolls_back_receipt(){var p=Payment(await Originate());await using var db=Receipts();var suffix=Identity();var function="reject_"+suffix;var sql=$"CREATE FUNCTION {function}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.\"Identity\" = 'demo-bank:{p.EventId}' THEN RAISE EXCEPTION 'injected atomicity failure'; END IF; RETURN NEW; END; $$; CREATE TRIGGER {function} BEFORE INSERT ON outbox FOR EACH ROW EXECUTE FUNCTION {function}();";await db.Database.ExecuteSqlRawAsync(sql);try{using var response=await Deliver(p);Assert.Equal(HttpStatusCode.ServiceUnavailable,response.StatusCode);Assert.False(await db.Receipts.AnyAsync(x=>x.EventId==p.EventId));}finally{await db.Database.ExecuteSqlRawAsync($"DROP TRIGGER {function} ON outbox; DROP FUNCTION {function}();");}}
    [Fact]public async Task Duplicate_webhook_produces_one_balanced_financial_result(){var r=await Originate();var p=Payment(r);using var a=await Deliver(p);using var b=await Deliver(p);Assert.Equal(HttpStatusCode.OK,b.StatusCode);var result=await WaitPayment(p.BankTransactionId);Assert.Equal("Applied",result.Status);await using var db=Db();var loan=await db.Loans.SingleAsync(x=>x.Reference==r);Assert.Equal(9_200_000,loan.OutstandingPrincipal);Assert.Equal(1,await db.Journals.CountAsync(x=>x.PaymentId==result.Id));var journal=await db.Journals.Include(x=>x.Postings).SingleAsync(x=>x.PaymentId==result.Id);Assert.Equal(journal.Postings.Sum(x=>x.Debit),journal.Postings.Sum(x=>x.Credit));}
    [Fact]public async Task Different_event_same_transaction_does_not_apply_twice(){var p=Payment(await Originate());await using(var db=Db())await new PaymentProcessor(db).Apply(Envelope(p));await using(var db=Db())await new PaymentProcessor(db).Apply(Envelope(p with{EventId="new-"+Identity()}));await using(var db=Db()){var result=await db.Payments.SingleAsync(x=>x.BankTransactionId==p.BankTransactionId);Assert.Equal(2,result.Attempts);Assert.Equal(1,await db.Journals.CountAsync(x=>x.PaymentId==result.Id));}}
    [Fact]public async Task Conflicting_event_and_transaction_fields_are_reviewed(){var p=Payment(await Originate());using var a=await Deliver(p);using var conflict=await Deliver(p with{AmountMinor="800000"});Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);await WaitPayment(p.BankTransactionId);await using var db=Db();await new PaymentProcessor(db).Apply(Envelope(p with{EventId="conflict-"+Identity(),Status="FAILED"}));Assert.True(await db.Conflicts.AnyAsync(x=>x.BankTransactionId==p.BankTransactionId));Assert.Equal("Applied",(await db.Payments.SingleAsync(x=>x.BankTransactionId==p.BankTransactionId)).Status);}
    [Fact]public async Task Concurrent_distinct_payments_preserve_totals_and_journals(){var r=await Originate();await Task.WhenAll(Enumerable.Range(0,20).Select(async _=>{await using var db=Db();await new PaymentProcessor(db).Apply(Envelope(Payment(r,amount:"50000")));}));await using var check=Db();var l=await check.Loans.Include(x=>x.Installments).SingleAsync(x=>x.Reference==r);Assert.Equal(9_200_000,l.OutstandingPrincipal);Assert.Equal(100_000,l.PaidInterest);Assert.Equal(100_000,l.UnappliedCredit);Assert.Equal(800_000,l.Installments.Sum(x=>x.PaidPrincipal));var journals=await check.Journals.Include(x=>x.Postings).Where(x=>x.LoanId==l.Id).ToListAsync();Assert.Equal(21,journals.Count);Assert.All(journals,j=>Assert.Equal(j.Postings.Sum(x=>x.Debit),j.Postings.Sum(x=>x.Credit)));}
    [Fact]public async Task Crash_after_commit_before_ack_redelivers_without_another_journal(){var p=Payment(await Originate());var queue="test.crash."+Identity();var factory=new ConnectionFactory{Uri=new Uri(Env("RABBITMQ_URL","amqp://lms:local-rabbitmq-password-2026@localhost:5672"))};await using(var c=await factory.CreateConnectionAsync()){await using var channel=await c.CreateChannelAsync(new CreateChannelOptions(true,true));await channel.QueueDeclareAsync(queue,true,false,false);await Broker.Publish(channel,queue,p.EventId,Encoding.UTF8.GetBytes(JsonSerializer.Serialize(Envelope(p),Contracts.Json)),0,null,CancellationToken.None);var delivery=await channel.BasicGetAsync(queue,false);Assert.NotNull(delivery);await using var db=Db();await new PaymentProcessor(db).Apply(JsonSerializer.Deserialize<PaymentReceived>(delivery.Body.Span,Contracts.Json)!);/* Deliberately close connection with no ACK. */}await using(var c=await factory.CreateConnectionAsync()){await using var channel=await c.CreateChannelAsync();BasicGetResult? delivery=null;for(var i=0;i<30&&delivery is null;i++){delivery=await channel.BasicGetAsync(queue,false);if(delivery is null)await Task.Delay(100);}Assert.NotNull(delivery);Assert.True(delivery.Redelivered);await using var db=Db();var result=await new PaymentProcessor(db).Apply(JsonSerializer.Deserialize<PaymentReceived>(delivery.Body.Span,Contracts.Json)!);await channel.BasicAckAsync(delivery.DeliveryTag,false);Assert.Equal(1,await db.Journals.CountAsync(x=>x.PaymentId==result.Id));await channel.QueueDeleteAsync(queue);}}
    [Fact]public async Task Unknown_reference_can_resolve_and_replay_safely(){var r=await Originate();var p=Payment("UNKNOWN-"+Identity());using var response=await Deliver(p);Assert.Equal("Unmatched",(await WaitPayment(p.BankTransactionId)).Status);using var client=await Client("Admin");using var resolved=await client.PostAsJsonAsync($"/api/v1/payments/{p.BankTransactionId}/resolve",new {reference=r});resolved.EnsureSuccessStatusCode();using var replay=await client.PostAsync($"/api/v1/payments/{p.BankTransactionId}/replay",null);replay.EnsureSuccessStatusCode();using var again=await client.PostAsync($"/api/v1/payments/{p.BankTransactionId}/replay",null);again.EnsureSuccessStatusCode();await using var db=Db();Assert.Equal(1,await db.Journals.CountAsync(x=>x.Kind=="Payment"&&x.LoanId==db.Loans.Where(l=>l.Reference==r).Select(l=>l.Id).First()));Assert.True(await db.Audits.AnyAsync(x=>x.Identity==p.BankTransactionId&&x.Action=="ResolveReference"));}
    [Fact]public async Task Bank_failed_never_posts_money(){var p=Payment(await Originate(),outcome:"FAILED");await using var db=Db();var result=await new PaymentProcessor(db).Apply(Envelope(p));Assert.Equal("BankDeclined",result.Status);Assert.False(await db.Journals.AnyAsync(x=>x.PaymentId==result.Id));}
    [Fact]public async Task Financial_failure_before_commit_rolls_back_every_effect()
    {
        var reference=await Originate();var payment=Payment(reference);var suffix=Identity();var name="reject_journal_"+suffix;
        await using var setup=Db();
        await setup.Database.ExecuteSqlRawAsync($"CREATE FUNCTION {name}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.\"Identity\" = 'payment:demo-bank:{payment.BankTransactionId}' THEN RAISE EXCEPTION 'injected financial rollback'; END IF; RETURN NEW; END; $$; CREATE TRIGGER {name} BEFORE INSERT ON journals FOR EACH ROW EXECUTE FUNCTION {name}();");
        try
        {
            await using(var attempt=Db())await Assert.ThrowsAsync<DbUpdateException>(()=>new PaymentProcessor(attempt).Apply(Envelope(payment)));
            await using var check=Db();var loan=await check.Loans.Include(x=>x.Installments).SingleAsync(x=>x.Reference==reference);
            Assert.Equal(10_000_000,loan.OutstandingPrincipal);Assert.Equal(0,loan.PaidInterest);Assert.All(loan.Installments,i=>{Assert.False(i.InterestRecognized);Assert.Equal(0,i.PaidPrincipal);Assert.Equal(0,i.PaidInterest);});
            Assert.False(await check.Payments.AnyAsync(x=>x.BankTransactionId==payment.BankTransactionId));Assert.False(await check.Journals.AnyAsync(x=>x.LoanId==loan.Id));
            Assert.False(await check.Outbox.AnyAsync(x=>x.Payload.Contains(payment.BankTransactionId)));
        }
        finally {await setup.Database.ExecuteSqlRawAsync($"DROP TRIGGER {name} ON journals; DROP FUNCTION {name}();");}
    }
    [Fact]public async Task Retry_exhaustion_preserves_identity_and_admin_replay_recovers_once()
    {
        var reference=await Originate();var payment=Payment(reference);var name="reject_retry_"+Identity();var removed=false;
        await using var setup=Db();
        await setup.Database.ExecuteSqlRawAsync($"CREATE FUNCTION {name}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.\"Identity\" = 'payment:demo-bank:{payment.BankTransactionId}' THEN RAISE EXCEPTION 'injected retryable database failure'; END IF; RETURN NEW; END; $$; CREATE TRIGGER {name} BEFORE INSERT ON journals FOR EACH ROW EXECUTE FUNCTION {name}();");
        try
        {
            using(var receipt=await Deliver(payment))receipt.EnsureSuccessStatusCode();
            FailedEnvelope? failure=null;
            for(var i=0;i<1200&&failure is null;i++){await using var poll=Db();failure=await poll.Failures.AsNoTracking().SingleOrDefaultAsync(x=>x.Identity=="demo-bank:"+payment.EventId);if(failure is null)await Task.Delay(100);}
            Assert.NotNull(failure);Assert.Equal(4,failure.Attempts);Assert.Contains(payment.BankTransactionId,failure.Payload);Assert.False(await setup.Payments.AnyAsync(x=>x.BankTransactionId==payment.BankTransactionId));
            await setup.Database.ExecuteSqlRawAsync($"DROP TRIGGER {name} ON journals; DROP FUNCTION {name}();");removed=true;
            using var client=await Client("Admin");using(var replay=await client.PostAsync("/api/v1/failures/"+failure.Id+"/replay",null))replay.EnsureSuccessStatusCode();
            var applied=await WaitPayment(payment.BankTransactionId);Assert.Equal("Applied",applied.Status);
            await using var check=Db();Assert.Equal(1,await check.Journals.CountAsync(x=>x.PaymentId==applied.Id));Assert.True(await check.Audits.AnyAsync(x=>x.Action=="ReplayFailedEnvelope"&&x.Identity==failure.Identity));
        }
        finally {if(!removed)await setup.Database.ExecuteSqlRawAsync($"DROP TRIGGER {name} ON journals; DROP FUNCTION {name}();");}
    }
    [Theory][InlineData("50000",10_000_000,50_000,0)][InlineData("1000000",9_200_000,100_000,100_000)]public async Task Partial_and_excess_policy_is_persisted(string amount,long principal,long interest,long credit){var r=await Originate();await using var db=Db();await new PaymentProcessor(db).Apply(Envelope(Payment(r,amount:amount)));var l=await db.Loans.SingleAsync(x=>x.Reference==r);Assert.Equal(principal,l.OutstandingPrincipal);Assert.Equal(interest,l.PaidInterest);Assert.Equal(credit,l.UnappliedCredit);}
    [Fact]public async Task Invalid_signature_never_creates_a_receipt(){var p=Payment(await Originate());using var response=await Deliver(p,false);Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);await using var db=Receipts();Assert.False(await db.Receipts.AnyAsync(x=>x.EventId==p.EventId));}
    [Fact]public async Task Notification_redelivery_creates_one_in_app_record(){var id=Identity();var result=new PaymentResult("notification-test-"+id,"notification-tx-"+id,"demo-bank",DateTimeOffset.UtcNow,1,id,null,"LOAN-1001","Applied","900000");var factory=new ConnectionFactory{Uri=new Uri(Env("RABBITMQ_URL","amqp://lms:local-rabbitmq-password-2026@localhost:5672"))};await using(var connection=await factory.CreateConnectionAsync()){await using var channel=await connection.CreateChannelAsync(new CreateChannelOptions(true,true));for(var i=0;i<2;i++)await Broker.Publish(channel,Contracts.ResultsQueue,result.EventId,Encoding.UTF8.GetBytes(JsonSerializer.Serialize(result,Contracts.Json)),0,null,CancellationToken.None);}using var client=await Client("Admin");JsonArray? records=null;for(var i=0;i<100;i++){records=await client.GetFromJsonAsync<JsonArray>("/api/v1/notifications?transactionId="+result.BankTransactionId);if(records?.Count>0)break;await Task.Delay(100);}Assert.NotNull(records);Assert.Single(records);}
    [Fact]public async Task Service_database_credentials_cannot_connect_to_another_service_database(){var connection=new Npgsql.NpgsqlConnection(Connection("webhook").Replace("Database=webhook","Database=loan",StringComparison.Ordinal));await using(connection){var error=await Assert.ThrowsAsync<Npgsql.PostgresException>(async()=>await connection.OpenAsync());Assert.Equal("42501",error.SqlState);}}
    [Fact]public async Task Observer_cannot_invoke_operational_controls(){using var client=await Client("Observer");foreach(var path in new[]{"/api/v1/runs","/api/v1/payments/fake/replay","/api/v1/payments/fake/resolve","/api/v1/transactions/fake/redeliver","/api/v1/failures/"+Guid.NewGuid()+"/replay"}){using var response=await client.PostAsJsonAsync(path,new {reference="LOAN-1001"});Assert.Equal(HttpStatusCode.Forbidden,response.StatusCode);}}
    [Fact]public async Task Missing_webhook_is_reconciled_and_recovered_once(){var r=await Originate();using var client=await Client("Admin");using var response=await client.PostAsJsonAsync("/api/v1/runs",new {preset="Integration missing",targetRps=1,durationSeconds=1,concurrency=1,missingPercent=100,loanReference=r});response.EnsureSuccessStatusCode();var run=JsonNode.Parse(await response.Content.ReadAsStringAsync())!["id"]!.GetValue<string>();await Task.Delay(5500);var report=await client.GetFromJsonAsync<JsonNode>($"/api/v1/reconciliation/{run}?graceSeconds=5");Assert.Equal(1,report!["counts"]!["MissingReceipt"]!.GetValue<int>());var id=report["items"]![0]!["bankTransactionId"]!.GetValue<string>();for(var i=0;i<2;i++){using var recover=await client.PostAsync($"/api/v1/transactions/{id}/redeliver",null);recover.EnsureSuccessStatusCode();}var p=await WaitPayment(id);await using var db=Db();Assert.Equal(1,await db.Journals.CountAsync(x=>x.PaymentId==p.Id));report=await client.GetFromJsonAsync<JsonNode>($"/api/v1/reconciliation/{run}?graceSeconds=5");Assert.Equal(1,report!["counts"]!["Matched"]!.GetValue<int>());Assert.Equal("900000",report["totals"]!["Matched"]!.GetValue<string>());}
}
